parameters.jsonBody:
{
  "model": "bytedance/seedance-2-mini",
  "input": {
    "prompt": "A serene beach at sunset with waves gently crashing on the shore, palm trees swaying in the breeze, and seagulls flying across the orange sky",
    "return_last_frame": false,
    "generate_audio": false,
    "resolution": "480p",
    "aspect_ratio": "16:9",
    "duration": 5,
    "web_search": false
  }
}

parameters.jsCode:
const item = $input.first().json;

// Data is nested inside item.data
const data = item.data;

// Parse resultJson string into object
const resultJson = typeof data.resultJson === 'string'
  ? JSON.parse(data.resultJson)
  : data.resultJson;

// Extract clean video URL
const videoUrl = resultJson.resultUrls[0];

return [{
  json: {
    videoUrl: videoUrl,
    taskId: data.taskId,
    model: data.model,
    state: data.state,
    creditsConsumed: data.creditsConsumed,
    costTime: data.costTime
  }
}];

